insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('JO', 'default', 'Jordan reference chart of accounts', '{"en":"Jordan reference chart of accounts"}'::jsonb, true, 'companies', array['JO-IFRS-IS', 'JO-IFRS-SFP']::text[], null, 'No legal chart of accounts for Jordanian companies in general was found in the texts read. What the IFRS Foundation profile records is the reporting framework: IFRS Standards are required for the companies whose securities trade in a public market, and the profile was not read for the rest. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-style statements below (IAS 1, expenses by nature), with the accounts a Jordanian trading company keeps — general tax output and input, the tax on imports owed to Customs at the border, the tax on imported services owed to the Department, income tax withheld, social security contributions and the special tax.', 'ifrs-jordan-profile')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

