insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('JO', 'JO-GST', 'General sales tax return', array['bimonth']::declaration_period[], null, date '2009-12-27', null, 'Article 16 of the General Sales Tax Law No. 6 of 1994 as amended — a registered person subject to the general tax files a two-month return, the two months being one tax period, and the Director sets where the periods begin and end (the pack anchors them on January, March, May and so on, which the format requires and the text does not say); the Director may extend a period to six months at most; a person subject to the special tax files a month return, which the pack does not model. The return is the ISTD form CED:PR15.F12. The pack carries the lines a document writes into (2, 3, 5 to 10) and the totals of lines 14 and 15; the carry-forward, the adjustments and the refund claims (lines 1, 11, 12, 13, 16 to 19) are the preparer''s.', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

