  ('JO', 'JO-GST', '6c', 'base', 'Line 6 — Domestic sales taxed at 4 % — value', '{"en":"Line 6 — Domestic sales taxed at 4 % — value"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST return (form CED:PR15.F12, "إقرار بالضريبة العامة على المبيعات", updated 7 November 2022), line 6, domestic sales taxed at 4 %: the value of the supplies, tax excluded.', 'gst-return'),
