update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Article 18(a) of the General Sales Tax Law — the registered person issues tax invoices as specified by the executive instructions (Instructions No. (6) of 2003 pertaining to invoices and records, listed in the consolidated text and not found in English). No text read states how invoices are numbered. `sequential` and the number format are conventions of this pack and not rules of the law.',
  numbering_source_key          = 'gst-law',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Article 9(a) of the General Sales Tax Law — the tax on goods becomes due at whichever comes first of the delivery of the goods, the issue of the tax invoice or the receipt of payment, wholly or partly; Article 9(b) — on a service, of the issue of the tax invoice or the receipt of payment; Article 9(c) — payable on the value covered by the invoice or the payment, whichever is higher. That is a three-way earliest test for goods and a two-way one for services, and the closed vocabulary of this field has no value for either; `earliest_of_delivery_or_payment` is the nearest and is what the rule reduces to in the ordinary case. A supply invoiced ahead of delivery or payment is the case this approximation misses.',
  tax_point_source_key          = 'gst-law',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Jordan runs a national e-invoicing system, JoFotara, whose registration portal is open to the public; the text that says who must issue through it, from when, and in what format was not read (the portal opens on a login page, and the Department''s pages read did not reproduce the instructions). `obligation` is `none` for want of a text, not on a finding that none exists, and no brick of the formats package writes the JoFotara message, so the four fields above would describe a capability this pack does not have. A taxpayer in the scope of JoFotara issues through the portal and keeps the books here; see the README.',
  einvoice_source_key           = 'jofotara',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'JO';

update country_defaults set
  tax_payee_name       = 'Income and Sales Tax Department (ISTD)',
  tax_payee_source_key = 'istd-portal'
 where country = 'JO';
